def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value:
    :type value: Point
    :return: a JSON‑serialisable representation of the point
    """
    # If the value is already a tuple or list, assume it contains coordinates
    if isinstance(value, (tuple, list)):
        coords = list(value)
        if len(coords) == 2:
            return {"x": coords[0], "y": coords[1]}
        if len(coords) == 3:
            return {"x": coords[0], "y": coords[1], "z": coords[2]}
        raise ValueError("Point must have 2 or 3 coordinates")

    # Try to extract x, y, z attributes (common for dataclasses, namedtuples, etc.)
    attrs = {}
    for attr in ("x", "y", "z"):
        if hasattr(value, attr):
            attrs[attr] = getattr(value, attr)
    if attrs:
        # If only x and y are present, return them; otherwise include z if present
        return attrs

    # Fallback: try to iterate over the value
    try:
        coords = list(value)
        if len(coords) == 2:
            return {"x": coords[0], "y": coords[1]}
        if len(coords) == 3:
            return {"x": coords[0], "y": coords[1], "z": coords[2]}
    except TypeError:
        pass

    raise TypeError(f"Cannot dehydrate point: {value!r}")

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    # Attempt to return keys from a dict-like attribute if present
    for attr in ('_data', '_record', 'data', 'record'):
        if hasattr(self, attr):
            value = getattr(self, attr)
            if isinstance(value, dict):
                return list(value.keys())
    # Fallback to the instance's __dict__ keys
    return list(self.__dict__.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    for i, item in enumerate(self):
        if item == key:
            return i
    raise ValueError(f"{key} is not in list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # If no keys are provided, return all values
    if not keys:
        # Use the underlying mapping's values to avoid recursion
        try:
            return list(super().values())
        except Exception:
            # Fallback: try to construct a dict from self
            return list(dict(self).values())

    # Prepare a list of all items to support index-based access
    try:
        items = list(super().items())
    except Exception:
        items = list(dict(self).items())

    result = []
    for key in keys:
        if isinstance(key, int):
            # Index-based access
            try:
                result.append(items[key][1])
            except IndexError:
                raise KeyError(f"Index {key} out of range")
        else:
            # Key-based access
            try:
                result.append(super().__getitem__(key))
            except Exception:
                # Fallback to dict lookup if super() fails
                try:
                    result.append(dict(self)[key])
                except KeyError:
                    raise KeyError(f"Key {key} not found")
    return result

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key.
    Keys provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of
    bounds will trigger an IndexError.
    """
    # Determine the list of keys and values for the record
    if hasattr(self, "_keys") and hasattr(self, "_values"):
        keys_list = list(self._keys)
        values_list = list(self._values)
    elif hasattr(self, "_data") and isinstance(self._data, dict):
        keys_list = list(self._data.keys())
        values_list = list(self._data.values())
    elif hasattr(self, "keys") and hasattr(self, "values"):
        keys_list = list(self.keys())
        values_list = list(self.values())
    else:
        raise AttributeError("Record does not provide keys and values")

    # If no specific keys are requested, return all
    if not keys:
        return dict(zip(keys_list, values_list))

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(values_list):
                raise IndexError(f"Index {key} out of bounds")
            result[keys_list[key]] = values_list[key]
        else:
            if key in keys_list:
                idx = keys_list.index(key)
                result[key] = values_list[idx]
            else:
                result[key] = None
    return result

def round_half_to_even(n):
    """
    Round a number to the nearest integer, with halves rounded to the nearest even integer.
    """
    # Determine floor and ceil without importing math
    if n >= 0:
        floor_n = int(n)
        ceil_n = floor_n if n == floor_n else floor_n + 1
    else:
        ceil_n = int(n)
        floor_n = ceil_n if n == ceil_n else ceil_n - 1

    diff_floor = n - floor_n
    diff_ceil = ceil_n - n

    if diff_floor < diff_ceil:
        return floor_n
    if diff_floor > diff_ceil:
        return ceil_n

    # Tie: round to nearest even
    if floor_n % 2 == 0:
        return floor_n
    else:
        return ceil_n

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Prepare class attributes: store the SRID mapping and initialize each field to None
    attrs = {'_srid_map': srid_map}
    for field in fields:
        attrs[field] = None
    # Create and return the new subclass of Point
    return type(name, (Point,), attrs)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        import warnings
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    return tuple(int(part) for part in re.findall(r'\d+', s))

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            k = key(*args, **kwargs)
            # Try to get from cache
            if lock:
                if hasattr(lock, "__enter__"):
                    with lock:
                        if k in cache:
                            return cache[k]
                else:
                    lock.acquire()
                    try:
                        if k in cache:
                            return cache[k]
                    finally:
                        lock.release()
            else:
                if k in cache:
                    return cache[k]
            # Compute result
            result = func(*args, **kwargs)
            # Store in cache
            if lock:
                if hasattr(lock, "__enter__"):
                    with lock:
                        cache[k] = result
                else:
                    lock.acquire()
                    try:
                        cache[k] = result
                    finally:
                        lock.release()
            else:
                cache[k] = result
            return result
        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if maxsize <= 0:
        # No caching
        def decorator(func):
            return func
        return decorator

    def decorator(func):
        cache = {}
        # key -> (value, count)
        def _make_key(args, kwargs):
            key = args
            if kwargs:
                # sort kwargs to make key deterministic
                items = tuple(sorted(kwargs.items()))
                key += items
            if typed:
                key += tuple(type(v) for v in args)
                if kwargs:
                    key += tuple(type(v) for _, v in items)
            return key

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs)
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                return value
            # compute result
            result = func(*args, **kwargs)
            # add to cache
            if len(cache) >= maxsize:
                # find key with minimum count
                min_key = None
                min_count = None
                for k, (_, c) in cache.items():
                    if min_count is None or c < min_count:
                        min_count = c
                        min_key = k
                if min_key is not None:
                    del cache[min_key]
            cache[key] = (result, 1)
            return result

        return wrapper

    return decorator

def setdefault(self, key, default=None):
    if key in self:
        return self[key]
    self[key] = default
    return default

def get(self, key, default=None):
    if key in self:
        return self[key]
    return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.
    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Compute cache key
            try:
                k = key(*args, **kwargs)
            except Exception:
                # If key function fails, just call the function
                return func(*args, **kwargs)
            # Define inner function to get or set cache
            def get_or_set():
                # Try to get from cache
                if hasattr(cache, "__contains__"):
                    if k in cache:
                        return cache[k]
                else:
                    try:
                        return cache[k]
                    except Exception:
                        pass
                # Not in cache, compute
                result = func(*args, **kwargs)
                try:
                    cache[k] = result
                except Exception:
                    # If cache is read-only or doesn't support assignment, ignore
                    pass
                return result
            # Acquire lock if provided
            if lock is not None:
                # If lock is a context manager
                if hasattr(lock, "__enter__") and hasattr(lock, "__exit__"):
                    with lock:
                        return get_or_set()
                else:
                    # Assume lock has acquire/release
                    lock.acquire()
                    try:
                        return get_or_set()
                    finally:
                        lock.release()
            else:
                return get_or_set()
        # Preserve function metadata
        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        wrapper.__module__ = func.__module__
        wrapper.__qualname__ = func.__qualname__
        return wrapper
    return decorator

@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        import os
        return os.path.isfile(file_name)
    except Exception:
        return False

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = {}
    # Determine which classes to inspect
    classes = [self.__class__]
    if all:
        classes = self.__class__.__mro__
    for cls in classes:
        for name, value in cls.__dict__.items():
            # Skip private and special attributes
            if name.startswith('_'):
                continue
            # Try to get a description from a 'description' attribute or the docstring
            desc = None
            if hasattr(value, 'description'):
                desc = getattr(value, 'description')
            elif hasattr(value, '__doc__') and value.__doc__:
                desc = value.__doc__
            if desc:
                # Only set if not already present (to preserve subclass overrides)
                if name not in result:
                    result[name] = desc
    return result

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    if sequence is None:
        return output
    for arg in sequence:
        # Expand nested sequences (lists or tuples) but leave other objects intact.
        if isinstance(arg, (list, tuple)) and not isinstance(arg, str):
            _normalizeargs(arg, output)
        else:
            output.append(arg)
    return output

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    return not _c_optimizations_required()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Ensure the attribute exists
    if not hasattr(self, "_err_indices"):
        raise AttributeError("The object does not have an '_err_indices' attribute.")
    # Retrieve the indices for the requested coordinate
    indices = self._err_indices.get(coord_name)
    if indices is None:
        raise KeyError(f"Coordinate '{coord_name}' not found in error indices.")
    return indices

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Direct instance of FillRequest
    if isinstance(seq, FillRequest):
        return True
    # Exclude Source sequences
    if isinstance(seq, Source):
        return False
    # Exclude string/bytes which are iterable but not sequences of objects
    if isinstance(seq, (str, bytes)):
        return False
    # Try to iterate over seq
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    for item in iterator:
        if isinstance(item, FillRequest):
            return True
    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'request', None))

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return callable(getattr(obj, 'run', None))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return (
        hasattr(obj, 'fill') and callable(getattr(obj, 'fill'))
        and hasattr(obj, 'compute') and callable(getattr(obj, 'compute'))
    )

def difference(d1, d2, level=-1):
    """
    Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    # Ensure level is an integer
    try:
        level = int(level)
    except Exception:
        level = -1

    # Helper to decide next level
    def next_level(cur):
        if cur == -1:
            return -1
        return cur - 1

    result = {}
    for key, val1 in d1.items():
        if key not in d2:
            # Key only in d1: include it
            result[key] = val1
        else:
            val2 = d2[key]
            # Both values are dicts
            if isinstance(val1, dict) and isinstance(val2, dict):
                if level == 0:
                    # No recursion: treat as equal if dicts are equal
                    if val1 != val2:
                        result[key] = val1
                else:
                    # Recurse
                    subdiff = difference(val1, val2, next_level(level))
                    if subdiff:
                        result[key] = subdiff
            else:
                # At least one is not a dict
                if val1 != val2:
                    result[key] = val1
    return result

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Simple regex patterns for Kubernetes-like labels
    KEY_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')
    VALUE_REGEX = re.compile(r'^[A-Za-z0-9]([A-Za-z0-9_.-]*[A-Za-z0-9])?$')

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not KEY_REGEX.match(key):
                errors.append({key: f"Label key '{key}' does not match the regex {KEY_REGEX.pattern}"})

        # Helper to validate a single value
        def _validate_value(val, key_context):
            if not isinstance(val, (str, bytes)):
                errors.append({str(val): 'expected string or bytes-like object'})
            else:
                if not VALUE_REGEX.match(val):
                    errors.append({val: f"Label value '{val}' does not match the regex {VALUE_REGEX.pattern}"})

        # Validate value(s)
        if isinstance(value, list):
            for v in value:
                _validate_value(v, key)
        else:
            _validate_value(value, key)

    if errors:
        # Assuming ValidationError accepts a list of error dicts as its message
        raise ValidationError(errors)

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Ensure we are working with lists
    if not isinstance(last_applied_manifest, list):
        last_applied_manifest = []
    if not isinstance(response, list):
        return last_applied_manifest

    # Iterate over each item in the response
    for idx, resp_item in enumerate(response):
        # If the last_applied_manifest does not have this index, create a placeholder
        if idx >= len(last_applied_manifest):
            # Determine the type of the placeholder based on the observer_schema
            # If observer_schema is a dict, we assume the item is a dict; otherwise, a list
            if isinstance(observer_schema, dict):
                placeholder = {}
            else:
                placeholder = []
            last_applied_manifest.append(placeholder)

        # Recursively update the item
        if isinstance(resp_item, dict):
            # If the placeholder is not a dict, replace it
            if not isinstance(last_applied_manifest[idx], dict):
                last_applied_manifest[idx] = {}
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[idx], observer_schema, resp_item
            )
        elif isinstance(resp_item, list):
            # If the placeholder is not a list, replace it
            if not isinstance(last_applied_manifest[idx], list):
                last_applied_manifest[idx] = []
            update_last_applied_manifest_list_from_resp(
                last_applied_manifest[idx], observer_schema, resp_item
            )
        else:
            # Primitive value: set directly if not already present
            if last_applied_manifest[idx] is None:
                last_applied_manifest[idx] = resp_item

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Prepare a dictionary to hold the default schemas
    default_schemas = {}

    # Retrieve the list of resources from the application manifest
    manifest = getattr(app.spec, "manifest", [])
    # Retrieve any custom observer schemas that have already been defined
    custom_schemas = getattr(app.spec, "observer_schema", {})

    # Iterate over each resource in the manifest
    for resource in manifest:
        # Ensure the resource is a mapping and has a kind
        if not isinstance(resource, dict):
            continue
        kind = resource.get("kind")
        if not kind:
            continue

        # Skip if a custom schema for this kind already exists
        if kind in custom_schemas:
            continue

        # Skip if we have already generated a default schema for this kind
        if kind in default_schemas:
            continue

        # Build a simple default JSON schema for the resource
        schema = {
            "type": "object",
            "properties": {
                "metadata": {
                    "type": "object",
                    "properties": {
                        "name": {"type": "string"},
                        "namespace": {"type": "string"},
                    },
                    "required": ["name"],
                },
                "spec": {"type": "object"},
                "status": {"type": "object"},
            },
            "required": ["metadata"],
        }

        # Store the generated schema
        default_schemas[kind] = schema

    return default_schemas

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Determine base status
    if hasattr(self, 'status'):
        status_attr = self.status
        base = status_attr() if callable(status_attr) else str(status_attr)
    else:
        try:
            is_valid = self.is_valid()
        except AttributeError:
            is_valid = getattr(self, 'valid', False)
        base = 'VALID' if is_valid else 'INVALID'
    # Append error and warning counts if available
    if hasattr(self, 'errors') and self.errors:
        base += f" ({len(self.errors)} errors)"
    if hasattr(self, 'warnings') and self.warnings:
        base += f" ({len(self.warnings)} warnings)"
    return f"{prefix}{base}"

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    # If the object does not have a log attribute, return an empty string.
    if not hasattr(self, '_log'):
        return ''
    # Build the string by converting each log entry to a string and
    # optionally prefixing it.
    return "\n".join(f"{prefix}{str(entry)}" for entry in self._log)

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type check
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")

    # Determine the spec version to use for validation
    spec_version = self.spec_version
    if extract_spec_version:
        type_val = inventory.get("type")
        if isinstance(type_val, str):
            # Map known type values to spec versions; extend as needed
            type_to_version = {
                "type1": "1.0",
                "type2": "2.0",
                "legacy": "0.9",
            }
            spec_version = type_to_version.get(type_val, spec_version)

    # Define required keys based on spec version
    if spec_version == "1.0":
        required_keys = {"name", "type"}
    elif spec_version == "2.0":
        required_keys = {"name", "type", "metadata"}
    else:
        # Default minimal requirements
        required_keys = {"name"}

    # Validate presence of required keys
    missing = required_keys - inventory.keys()
    if missing:
        raise ValueError(f"Missing required keys for spec version {spec_version}: {', '.join(sorted(missing))}")

    # Additional simple type checks (extend as needed)
    if "name" in inventory and not isinstance(inventory["name"], str):
        raise TypeError("inventory['name'] must be a string")
    if "type" in inventory and not isinstance(inventory["type"], str):
        raise TypeError("inventory['type'] must be a string")
    if "metadata" in inventory and not isinstance(inventory["metadata"], dict):
        raise TypeError("inventory['metadata'] must be a dictionary")

    # If all checks pass, return True
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is not None
    if prior is None:
        raise ValueError("prior cannot be None")
    # Ensure prior is the same type as self
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")
    # Ensure prior is not the same object
    if prior is self:
        raise ValueError("prior cannot be the same as self")
    # Ensure both objects have a 'version' attribute
    if not hasattr(prior, "version"):
        raise AttributeError("prior object lacks 'version' attribute")
    if not hasattr(self, "version"):
        raise AttributeError("self object lacks 'version' attribute")
    # Compare versions
    try:
        if prior.version >= self.version:
            raise ValueError(f"prior.version ({prior.version}) must be less than self.version ({self.version})")
    except TypeError:
        raise TypeError("prior.version and self.version must be comparable")
    # Ensure both objects have an 'inventory' attribute
    if not hasattr(prior, "inventory"):
        raise AttributeError("prior object lacks 'inventory' attribute")
    if not hasattr(self, "inventory"):
        raise AttributeError("self object lacks 'inventory' attribute")
    prior_inv = prior.inventory
    self_inv = self.inventory
    # If inventories are dictionaries, check that prior's items are present and quantities are not greater
    if isinstance(prior_inv, dict) and isinstance(self_inv, dict):
        for key, val in prior_inv.items():
            if key not in self_inv:
                raise ValueError(f"Item '{key}' in prior inventory not present in current inventory")
            try:
                if val > self_inv[key]:
                    raise ValueError(f"Quantity of item '{key}' in prior ({val}) exceeds current ({self_inv[key]})")
            except TypeError:
                # If values are not comparable, skip quantity check
                pass
    else:
        # Fallback: treat inventories as iterable collections
        try:
            prior_set = set(prior_inv)
            self_set = set(self_inv)
            if not prior_set.issubset(self_set):
                missing = prior_set - self_set
                raise ValueError(f"Items {missing} in prior inventory not present in current inventory")
        except TypeError:
            raise TypeError("inventory attributes must be dicts or iterable collections")
    # If all checks pass, return True
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Find the requested version in the inventory
    versions = inventory.get("versions", [])
    target_index = None
    for i, v in enumerate(versions):
        if v.get("id") == version:
            target_index = i
            break

    if target_index is None:
        # Version not found; return an empty mapping
        return {}

    # Start with the state of the target version
    target_state = versions[target_index].get("state", {})
    logical_path_map = {lp: set(files) for lp, files in target_state.items()}

    # Include content files from later versions that refer to the same logical paths
    for later_version in versions[target_index + 1 :]:
        later_state = later_version.get("state", {})
        for lp, files in later_state.items():
            if lp in logical_path_map:
                logical_path_map[lp].update(files)

    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """
    Validate the fixity block in an inventory.

    Parameters
    ----------
    fixity : dict or list
        The fixity block to validate. It can be a dictionary where keys are
        file names and values are dictionaries containing 'hash' and
        'algorithm', or a list of dictionaries each containing 'file',
        'hash', and 'algorithm'.
    manifest_files : iterable
        An iterable of file names that are present in the manifest. Only
        these files may be referenced in the fixity block.

    Returns
    -------
    list
        A list of error messages. An empty list indicates that the
        fixity block is valid.
    """
    errors = []

    # Normalise manifest files to a set for fast membership checks
    manifest_set = set(manifest_files)

    # Allowed hash algorithms
    allowed_algorithms = {"sha256", "sha1", "md5", "sha512"}

    if not fixity:
        # Nothing to validate
        return errors

    # Helper to validate a single entry
    def _validate_entry(file_name, entry, idx=None):
        local_errors = []
        if not isinstance(entry, dict):
            local_errors.append(
                f"Fixity entry for file '{file_name}' must be a dict."
            )
            return local_errors

        # Check required keys
        for key in ("hash", "algorithm"):
            if key not in entry:
                local_errors.append(
                    f"Missing '{key}' in fixity entry for file '{file_name}'."
                )
        # Validate hash
        if "hash" in entry:
            h = entry["hash"]
            if not isinstance(h, str) or not h:
                local_errors.append(
                    f"Invalid 'hash' value for file '{file_name}'."
                )
        # Validate algorithm
        if "algorithm" in entry:
            alg = entry["algorithm"]
            if not isinstance(alg, str) or not alg:
                local_errors.append(
                    f"Invalid 'algorithm' value for file '{file_name}'."
                )
            elif alg.lower() not in allowed_algorithms:
                local_errors.append(
                    f"Unsupported algorithm '{alg}' for file '{file_name}'."
                )
        return local_errors

    if isinstance(fixity, dict):
        # Each key is a file name
        for file_name, entry in fixity.items():
            if file_name not in manifest_set:
                errors.append(
                    f"Fixity references unknown file '{file_name}'."
                )
            errors.extend(_validate_entry(file_name, entry))
    elif isinstance(fixity, list):
        seen_files = set()
        for idx, entry in enumerate(fixity):
            if not isinstance(entry, dict):
                errors.append(
                    f"Fixity entry at index {idx} must be a dict."
                )
                continue
            if "file" not in entry:
                errors.append(
                    f"Missing 'file' key in fixity entry at index {idx}."
                )
                continue
            file_name = entry["file"]
            if file_name in seen_files:
                errors.append(
                    f"Duplicate fixity entry for file '{file_name}'."
                )
            seen_files.add(file_name)
            if file_name not in manifest_set:
                errors.append(
                    f"Fixity references unknown file '{file_name}'."
                )
            errors.extend(_validate_entry(file_name, entry, idx=idx))
    else:
        errors.append("Fixity block must be a dict or a list.")

    return errors

