def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    if node is None or not pubdate_xpaths:
        return None
    for xpath in pubdate_xpaths:
        try:
            result = node.xpath(xpath)
            if result:
                first = result[0]
                # If the xpath returns a string directly
                if isinstance(first, str):
                    return first
                # If it returns an element, return its text content
                if hasattr(first, "text"):
                    return first.text
                # Fallback: try to convert to string
                return str(first)
        except Exception:
            # Ignore malformed xpath or evaluation errors
            continue
    return None

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    visited = set()

    def _pretty(obj, level):
        # Avoid infinite recursion
        if id(obj) in visited:
            return ' ' * level + f'<recursion id={id(obj)}>'

        # Pretty print containers
        if isinstance(obj, (list, tuple, set)):
            visited.add(id(obj))
            lines = []
            for i, v in enumerate(obj):
                lines.append(' ' * level + f'[{i}]:')
                lines.append(_pretty(v, level + 2))
            visited.remove(id(obj))
            return '\n'.join(lines)

        if isinstance(obj, dict):
            visited.add(id(obj))
            lines = []
            for k, v in sorted(obj.items()):
                lines.append(' ' * level + f'{k}:')
                lines.append(_pretty(v, level + 2))
            visited.remove(id(obj))
            return '\n'.join(lines)

        # If the object has its own pretty method, use it (but avoid self recursion)
        if hasattr(obj, 'pretty') and obj is not self:
            return obj.pretty(level, debug)

        # Fallback to repr
        return ' ' * level + repr(obj)

    # Determine the object to pretty-print
    target = getattr(self, '__dict__', self)

    if debug:
        header = f'{self.__class__.__name__} (id={id(self)})'
        body = _pretty(target, indent)
        return header + '\n' + body
    else:
        return _pretty(target, indent)

def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        result = []
        for expr in args:
            # Handle AND expressions
            if isinstance(expr, And):
                # Absorption: A & (A | B) = A
                absorbed = False
                for sub in expr.args:
                    if isinstance(sub, Or):
                        for subsub in sub.args:
                            if subsub in expr.args:
                                result.append(subsub)
                                absorbed = True
                                break
                    if absorbed:
                        break
                if absorbed:
                    continue

                # Negative absorption: A & (~A | B) = A & B
                neg_absorbed = False
                for sub in expr.args:
                    if isinstance(sub, Or):
                        not_a = None
                        B = None
                        for subsub in sub.args:
                            if isinstance(subsub, Not):
                                not_a = subsub.args[0]
                            else:
                                B = subsub
                        if not_a is not None and not_a in expr.args and B is not None:
                            result.append(And(not_a, B))
                            neg_absorbed = True
                            break
                    if neg_absorbed:
                        break
                if neg_absorbed:
                    continue

                # No simplification
                result.append(expr)

            # Handle OR expressions
            elif isinstance(expr, Or):
                # Absorption: A | (A & B) = A
                absorbed = False
                for sub in expr.args:
                    if isinstance(sub, And):
                        for subsub in sub.args:
                            if subsub in expr.args:
                                result.append(subsub)
                                absorbed = True
                                break
                    if absorbed:
                        break
                if absorbed:
                    continue

                # Negative absorption: A | (~A & B) = A | B
                neg_absorbed = False
                for sub in expr.args:
                    if isinstance(sub, And):
                        not_a = None
                        B = None
                        for subsub in sub.args:
                            if isinstance(subsub, Not):
                                not_a = subsub.args[0]
                            else:
                                B = subsub
                        if not_a is not None and not_a in expr.args and B is not None:
                            result.append(Or(not_a, B))
                            neg_absorbed = True
                            break
                    if neg_absorbed:
                        break
                if neg_absorbed:
                    continue

                # No simplification
                result.append(expr)

            else:
                # Non-AND/OR expressions are left unchanged
                result.append(expr)

        return result

def get_versions():
    """Get version information or return default if unable to do so."""
    import subprocess
    try:
        # Get a human‑readable version string (e.g. tag or commit hash)
        version = subprocess.run(
            ["git", "describe", "--tags", "--always", "--dirty"],
            capture_output=True,
            text=True,
            check=True,
        ).stdout.strip()
        # Get the full commit hash
        full_rev = subprocess.run(
            ["git", "rev-parse", "HEAD"],
            capture_output=True,
            text=True,
            check=True,
        ).stdout.strip()
        return {"version": version, "full-revisionid": full_rev}
    except Exception:
        # Fallback to a default value when git is not available or an error occurs
        return {"version": "0+unknown", "full-revisionid": "unknown"}

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    for piece in pieces:
        if '+' in piece:
            return '.'
    return '+'

def register_vcs_handler(vcs, method=None):
    """
    Decorator factory that marks a function as the handler for a given VCS.
    It can be used with or without parentheses:

        @register_vcs_handler('git')
        def handle_git(...):
            ...

    or

        @register_vcs_handler('git', method=handle_git)
        def handle_git(...):
            ...

    The decorated function will receive an attribute `_vcs_handler`
    containing the VCS name.
    """
    # If only the VCS is provided, return a decorator that will receive the method.
    if method is None:
        return lambda m: register_vcs_handler(vcs, m)

    # Attach the VCS name to the function for later lookup.
    setattr(method, "_vcs_handler", vcs)
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os, hashlib

    num_objects = 0
    good_objects = 0

    # Determine the root directory to validate
    root = getattr(self, "storage_root", None)
    if not root or not os.path.isdir(root):
        if show_warnings:
            print(f"Storage root '{root}' is not a valid directory.")
        return num_objects, good_objects

    for dirpath, dirnames, filenames in os.walk(root):
        for filename in filenames:
            num_objects += 1
            file_path = os.path.join(dirpath, filename)
            is_valid = True

            # Basic object validation: can we read the file?
            if validate_objects:
                try:
                    with open(file_path, "rb") as f:
                        f.read(1)
                except Exception as e:
                    is_valid = False
                    if show_warnings:
                        print(f"Failed to read '{file_path}': {e}")

            # Optional digest check
            if check_digests and is_valid:
                digest_path = file_path + ".digest"
                if os.path.exists(digest_path):
                    try:
                        with open(file_path, "rb") as f:
                            data = f.read()
                        actual_digest = hashlib.sha256(data).hexdigest()
                        with open(digest_path, "r") as df:
                            expected_digest = df.read().strip()
                        if actual_digest != expected_digest:
                            is_valid = False
                            if show_warnings:
                                print(f"Digest mismatch for '{file_path}'.")
                    except Exception as e:
                        is_valid = False
                        if show_warnings:
                            print(f"Error checking digest for '{file_path}': {e}")

            if is_valid:
                good_objects += 1

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import json, os
    root = self.root_path
    if os.path.exists(root):
        raise FileExistsError(f"Root path {root} already exists.")
    # Create the root directory and the objects subdirectory
    os.makedirs(os.path.join(root, "objects"), exist_ok=True)
    # Prepare the .ocfl_root metadata file
    ocfl_root = {
        "ocfl_version": "1.0",
        "layout": "objects",
        "layout_version": "1.0",
        "layout_options": {
            "objects": {
                "layout": "objects",
                "layout_version": "1.0"
            }
        }
    }
    ocfl_root_path = os.path.join(root, ".ocfl_root")
    with open(ocfl_root_path, "w", encoding="utf-8") as f:
        json.dump(ocfl_root, f, indent=2)
    return ocfl_root_path

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if bug_ids is None:
        return params
    # Convert bug_ids to a comma‑separated string
    if isinstance(bug_ids, (list, tuple, set)):
        bug_ids_str = ",".join(str(bid) for bid in bug_ids)
    else:
        bug_ids_str = str(bug_ids)
    # Merge with existing 'ids' if present
    if "ids" in params:
        existing = params["ids"]
        if isinstance(existing, (list, tuple, set)):
            existing_str = ",".join(str(e) for e in existing)
        else:
            existing_str = str(existing)
        if existing_str:
            params["ids"] = ",".join([existing_str, bug_ids_str])
        else:
            params["ids"] = bug_ids_str
    else:
        params["ids"] = bug_ids_str
    return params

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        for opt in action.option_strings:
            if opt not in flags:
                flags.append(opt)
    return ' '.join(flags)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of flag strings (e.g., ['-f', '--foo'])
        flags.extend(action.option_strings)
    return ' '.join(flags)

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    if not subparsers:
        return {}, list(unparsed_arguments)

    parsed = {}
    unknown_sets = {}
    for name, parser in subparsers.items():
        ns, unknown = parser.parse_known_args(unparsed_arguments)
        parsed[name] = ns
        unknown_sets[name] = set(unknown)

    remaining = [arg for arg in unparsed_arguments
                 if all(arg in unknown_sets[name] for name in subparsers)]
    return parsed, remaining

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url
    for key, val in url_args.items():
        if val is None:
            continue
        placeholder_colon = f":{key}"
        placeholder_braces = f"{{{key}}}"
        url = url.replace(placeholder_colon, str(val))
        url = url.replace(placeholder_braces, str(val))
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if not isinstance(val, str):
        return False
    s = val.strip().lower()
    return s in {"none", "null", "nil", "na", "n/a", ""}

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Collect all option strings from the parser's actions
    flags = []
    for action in getattr(parser, "_actions", []):
        # Only include actions that have option strings (i.e., optional arguments)
        if getattr(action, "option_strings", None):
            flags.extend(action.option_strings)
    # Join the flags into a single space-separated string
    return " ".join(flags)

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        return value
    return value.replace('.', str(arg))

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string:
        return 0
    base = len(alphabet)
    # Build a mapping from character to its numeric value
    char_to_value = {ch: i for i, ch in enumerate(alphabet)}
    result = 0
    for ch in string:
        if ch not in char_to_value:
            raise ValueError(f"Character '{ch}' not in alphabet")
        result = result * base + char_to_value[ch]
    return result

def os_is_mac():
    """
    Checks if the os is macOS

    :return: True is macOS
    :rtype: bool
    """
    try:
        return os.uname().sysname == 'Darwin'
    except AttributeError:
        return False

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Remove leading and trailing single or double quotes
    return re.sub(r"(^['\"]|['\"]$)", "", name)

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(
            ['git', 'status', '--ignored', '--porcelain'],
            cwd=ignored,
            text=True
        )
    except (subprocess.CalledProcessError, FileNotFoundError):
        return ''
    ignored_files = []
    for line in output.splitlines():
        if line.startswith('!!'):
            parts = line.split(None, 1)
            if len(parts) == 2:
                ignored_files.append(parts[1])
    ignored_files.sort()
    return ','.join(ignored_files)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string checks
    if host.lower() == "localhost":
        return True
    if host == "127.0.0.1" or host == "::1":
        return True
    try:
        # Resolve the host to all possible addresses
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for family, _, _, _, sockaddr in infos:
        if family == socket.AF_INET:
            ip = sockaddr[0]
            if ip == "127.0.0.1" or ip.startswith("127."):
                return True
        elif family == socket.AF_INET6:
            ip = sockaddr[0]
            # Handle IPv4-mapped IPv6 addresses
            if ip == "::1" or ip.startswith("::ffff:127."):
                return True
    return False

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command
    if isinstance(commands, str):
        cmd = commands
        if args:
            cmd += ' ' + ' '.join(args)
        run_kwargs = {'shell': True, 'cwd': cwd, 'env': env, 'text': True, 'capture_output': True}
    else:
        cmd = list(commands) + list(args)
        run_kwargs = {'cwd': cwd, 'env': env, 'text': True, 'capture_output': True}
    if hide_stderr:
        run_kwargs['stderr'] = subprocess.DEVNULL
    if verbose:
        print(f"Running command: {cmd}")
    result = subprocess.run(cmd, **run_kwargs)
    if verbose:
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr)
    return result

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        addr = ipaddress.ip_address(target)
        return isinstance(addr, ipaddress.IPv4Address)
    except ValueError:
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        result = yaml.safe_dump(obj, default_flow_style=False, allow_unicode=True)
    else:
        result = yaml.dump(obj, Dumper=dumper, default_flow_style=False, allow_unicode=True)
    # Ensure the result is a unicode string in Python 2
    if isinstance(result, bytes):
        result = result.decode('utf-8')
    return result

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """
    Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    # Assume the class defines a mapping of supported protocol
    # versions to handler classes in the attribute `_protocol_handlers`.
    if protocol_version is None:
        # Return a shallow copy to prevent accidental mutation
        return dict(cls._protocol_handlers)

    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    if protocol_version in cls._protocol_handlers:
        return {protocol_version: cls._protocol_handlers[protocol_version]}
    return {}

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        bookmarks = cls()
        for raw in values:
            raw = raw.strip()
            if not raw:
                continue
            try:
                bookmark = Bookmark.from_raw_value(raw)
            except Exception:
                bookmark = Bookmark(raw)
            if hasattr(bookmarks, 'add'):
                bookmarks.add(bookmark)
            else:
                bookmarks.append(bookmark)
        return bookmarks

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Getter
    if other is None:
        return self.scale

    # Validate new scale
    if not isinstance(other, (int, float)):
        raise TypeError("Scale must be a numeric value")
    if self.scale is None or self.scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")

    # Compute scaling factor
    factor = other / self.scale

    # Determine the last coordinate field
    last_field = None
    if hasattr(self, "fields") and self.fields:
        last_field = self.fields[-1]

    # Rescale data
    if hasattr(self, "data"):
        data = self.data
        if isinstance(data, dict) and last_field in data:
            # Assume array-like
            try:
                data[last_field] = data[last_field] * factor
            except Exception:
                # Fallback for plain lists
                for i, val in enumerate(data[last_field]):
                    data[last_field][i] = val * factor
        elif isinstance(data, list):
            # List of rows
            for row in data:
                if row:
                    row[-1] *= factor
        else:
            # Assume numpy array or similar
            try:
                data[:, -1] = data[:, -1] * factor
            except Exception:
                pass

    # Rescale errors
    if hasattr(self, "errors"):
        errors = self.errors
        if isinstance(errors, dict) and last_field in errors:
            try:
                errors[last_field] = errors[last_field] * factor
            except Exception:
                for i, val in enumerate(errors[last_field]):
                    errors[last_field][i] = val * factor
        elif isinstance(errors, list):
            for row in errors:
                if row:
                    row[-1] *= factor
        else:
            try:
                errors[:, -1] = errors[:, -1] * factor
            except Exception:
                pass

    # Update scale
    self.scale = other
    return self

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    # Determine the style to use for conversion
    style = getattr(self, "_style", None)
    # Create and return the converter
    if style is None:
        return _converting._Converter()
    return _converting._Converter(style)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Helper to fetch a value from a dict or an object
    def _get_value(obj, key):
        if isinstance(obj, dict):
            return obj.get(key)
        return getattr(obj, key, None)

    # Check for a public message
    is_public = bool(_get_value(request, "public"))
    if is_public:
        # It's a Diaspora public request
        return True, True, False, False

    # Check for a private message
    is_private = bool(_get_value(request, "private"))
    if is_private:
        # It's a Diaspora private request
        return True, False, True, False

    # Check for a legacy payload
    is_legacy = bool(_get_value(request, "legacy"))
    if is_legacy:
        # It's a legacy Diaspora request
        return True, False, False, True

    # Not a Diaspora request
    return False, False, False, False

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        import urllib.request
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.headers.get('Content-Type')
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    import re
    # A valid tag consists of lowercase letters, digits, and hyphens.
    # It must not start or end with a hyphen, and must contain at least one character.
    return bool(re.fullmatch(r'[a-z0-9]+(?:-[a-z0-9]+)*', tag))

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}
    result = {}
    for child in node:
        result[child.tag] = child
    return result

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'"
        )

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    result = {"subject": None, "aliases": [], "links": []}

    # Try JSON first
    try:
        data = json.loads(document)
        # JSON format
        result["subject"] = data.get("subject")
        result["aliases"] = data.get("aliases", [])
        links = data.get("links", [])
        for link in links:
            # Ensure link is a dict
            if isinstance(link, dict):
                result["links"].append({
                    "rel": link.get("rel"),
                    "type": link.get("type"),
                    "href": link.get("href")
                })
        return result
    except Exception:
        pass  # Not JSON, try XML

    # Try XRD (XML)
    try:
        root = ET.fromstring(document)
        # Namespace handling: XRD may have namespace, but we can ignore
        # Find subject
        subject_elem = root.find(".//{*}subject")
        if subject_elem is not None and subject_elem.text:
            result["subject"] = subject_elem.text.strip()
        # Find aliases
        for alias_elem in root.findall(".//{*}alias"):
            if alias_elem.text:
                result["aliases"].append(alias_elem.text.strip())
        # Find links
        for link_elem in root.findall(".//{*}link"):
            rel = link_elem.get("rel")
            type_ = link_elem.get("type")
            href = link_elem.get("href")
            # Some XRD may use <uri> inside <link>
            if href is None:
                uri_elem = link_elem.find(".//{*}uri")
                if uri_elem is not None and uri_elem.text:
                    href = uri_elem.text.strip()
            if href:
                result["links"].append({
                    "rel": rel,
                    "type": type_,
                    "href": href
                })
        return result
    except Exception:
        # If parsing fails, return empty result
        return result

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json

    # Normalize handle: remove leading 'acct:' if present
    if handle.startswith('acct:'):
        handle = handle[5:]

    # Ensure handle contains a domain part
    if '@' not in handle:
        return {}

    # Build the webfinger URL
    resource = urllib.parse.quote(f'acct:{handle}')
    domain = handle.split('@', 1)[1]
    url = f'https://{domain}/.well-known/webfinger?resource={resource}'

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            if response.status != 200:
                return {}
            content = response.read().decode('utf-8')
            return json.loads(content)
    except Exception:
        return {}

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """
    Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Determine the request method to use
        method_lower = method.lower()
        if method_lower == "post":
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)
        elif method_lower == "put":
            response = requests.put(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            # Fallback to POST if an unsupported method is provided
            response = requests.post(url, data=data, timeout=timeout, *args, **kwargs)

        return (response.status_code, None)
    except Exception as exc:
        return (None, exc)

