@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        # Ensure we have content to validate
        if spec_content is None:
            raise IRValidatorException("Spec content is missing")

        # If the content is already a dictionary, use it directly
        if isinstance(spec_content, dict):
            spec_dict = spec_content
        else:
            # Attempt to parse YAML content
            try:
                import yaml
                spec_dict = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse spec content: {exc}")

        # Define mandatory fields that must be present in the spec
        required_fields = ["name", "version", "description"]

        # Check for missing mandatory fields
        missing = [field for field in required_fields if field not in spec_dict]
        if missing:
            raise IRValidatorException(
                f"Spec is missing mandatory fields: {', '.join(missing)}"
            )

        return spec_dict

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("No YAML file path provided")
    try:
        with open(yaml_file, "r") as f:
            data = yaml.safe_load(f)
    except Exception as exc:
        raise IRValidatorException(f"Failed to load YAML file '{yaml_file}': {exc}")
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file must contain a top‑level dictionary")
    required = getattr(cls, "REQUIRED_FIELDS", [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Helper to merge two dictionaries recursively
    def _merge_dicts(base, new):
        for k, v in new.items():
            if k in base and isinstance(base[k], dict) and isinstance(v, dict):
                base[k] = _merge_dicts(base[k], v)
            else:
                base[k] = v
        return base

    # Recursive resolver with cycle detection
    def _resolve(d, visited):
        includes = d.pop('include', [])
        if not isinstance(includes, list):
            includes = [includes]
        for inc in includes:
            if inc in visited:
                continue
            if inc not in self._specs:
                raise KeyError(f"Included group '{inc}' not found in specs.")
            visited.add(inc)
            inc_dict = self._specs[inc]
            resolved_inc = _resolve(inc_dict.copy(), visited)
            d = _merge_dicts(d, resolved_inc)
        return d

    return _resolve(parser_dict.copy(), set())

