    """Returning dict with options which deprecate others."""
    return {}

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []
    for opt in options_spec:
        name = opt.get('name')
        cond = opt.get('required_when')
        if not cond:
            continue
        try:
            # If the condition is a callable, call it with the args dict
            if callable(cond):
                if cond(args):
                    required.append(name)
            else:
                # Assume the condition is a string expression that can be evaluated
                # with the args dictionary as the local namespace.
                if eval(cond, {}, args):
                    required.append(name)
        except Exception:
            # If evaluation fails, ignore this option
            continue
    return required

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to allowed choices.
    # It is assumed that the class has an attribute `choices` which is a dict
    # mapping argument names to an iterable of allowed values.
    choices_map = getattr(self, "choices", {})
    for arg_name, value in args.items():
        # Skip arguments that do not have a defined set of choices.
        if arg_name not in choices_map:
            continue

        allowed = choices_map[arg_name]
        # If the value is None, we consider it valid (e.g., optional argument not provided).
        if value is None:
            continue

        # Support iterable values (e.g., list, tuple, set) for arguments that accept multiple values.
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v}. "
                        f"Allowed choices: {allowed}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value}. "
                    f"Allowed choices: {allowed}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine the iterable of values
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args

    for val in values:
        # Skip None values
        if val is None:
            return False
        # Try to convert to a number
        try:
            num = float(val)
        except (TypeError, ValueError):
            return False
        # Check against min and max bounds
        if not (self.min <= num <= self.max):
            return False
    return True

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Helper to process a key/value pair
    def _add_pair(key, value):
        if value is None:
            return
        if key.startswith('--control-'):
            control_args[key[len('--control-'):]] = value
        elif key.startswith('--nested-'):
            nested_args[key[len('--nested-'):]] = value
        elif key.startswith('--custom-'):
            # Custom args are treated as nested for the spec
            nested_args[key[len('--custom-'):]] = value

    # If args is a dict, iterate directly
    if isinstance(args, dict):
        for k, v in args.items():
            _add_pair(k, v)
    else:
        # Assume args is a list of strings or tuples
        i = 0
        while i < len(args):
            item = args[i]
            # Handle tuple pairs
            if isinstance(item, tuple) and len(item) == 2:
                key, value = item
                _add_pair(key, value)
                i += 1
                continue

            # Handle string arguments
            if isinstance(item, str) and item.startswith('--'):
                # Check for inline value with '='
                if '=' in item:
                    key, value = item.split('=', 1)
                    _add_pair(key, value)
                    i += 1
                else:
                    key = item
                    # Next element might be the value if it doesn't start with '--'
                    value = None
                    if i + 1 < len(args) and not isinstance(args[i + 1], str) or not args[i + 1].startswith('--'):
                        value = args[i + 1]
                        i += 2
                    else:
                        i += 1
                    _add_pair(key, value)
            else:
                # Skip non-argument items
                i += 1

    return control_args, nested_args

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        :return: The updated dictionary
        """
        if not extra_vars:
            return vars_dict

        for var in extra_vars:
            if not isinstance(var, str):
                continue
            if "=" not in var:
                continue
            key, value = var.split("=", 1)
            key = key.strip()
            value = value.strip()
            # If the value contains commas, treat it as a list
            if "," in value:
                # Preserve empty strings as empty list elements
                value = [v.strip() for v in value.split(",")]
            vars_dict[key] = value
        return vars_dict

