def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    # Import required modules inside the function to avoid global imports
    import os
    import json

    # Determine the plugin spec file name
    spec_file = None
    for name in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_file = path
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load the spec file (YAML or JSON)
    if spec_file.endswith(".json"):
        with open(spec_file, "r", encoding="utf-8") as f:
            data = json.load(f)
    else:
        try:
            import yaml
            with open(spec_file, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
        except Exception:
            # Fallback to JSON if YAML parsing fails
            with open(spec_file, "r", encoding="utf-8") as f:
                data = json.load(f)

    # Helper function to flatten nested dictionaries
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        default_path = os.path.join(os.getcwd(), 'config.yaml')
        os.environ['CONFIG_PATH'] = default_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'.")
    remainder = path[len(root):]
    if remainder.startswith('/') or remainder.startswith('\\'):
        remainder = remainder[1:]
    return remainder
